class Solution:
    def kthPalindrome(self, queries: List[int], intLength: int) -> List[int]:
        lo, hi = 10 ** (intLength - 1), 10 ** intLength
        pals = [x for x in range(lo, hi) if str(x) == str(x)[::-1]]
        return [pals[q - 1] if q <= len(pals) else -1 for q in queries]

