class Solution {
public:
    vector<long long> kthPalindrome(vector<int>& queries, int intLength) {
        long long lo = 1, hi = 1;
        for (int i = 0; i < intLength - 1; i++) lo *= 10;
        hi = lo * 10;
        vector<long long> pals;
        for (long long x = lo; x < hi; x++) {
            string s = to_string(x);
            string r(s.rbegin(), s.rend());
            if (s == r) pals.push_back(x);
        }
        vector<long long> res;
        for (int q : queries)
            res.push_back(q <= (long long)pals.size() ? pals[q - 1] : -1LL);
        return res;
    }
};

