class Solution {
    public long[] kthPalindrome(int[] queries, int intLength) {
        long lo = 1;
        for (int i = 0; i < intLength - 1; i++) lo *= 10;
        long hi = lo * 10;
        List<Long> pals = new ArrayList<>();
        for (long x = lo; x < hi; x++) {
            StringBuilder sb = new StringBuilder(Long.toString(x));
            if (Long.toString(x).contentEquals(sb.reverse())) pals.add(x);
        }
        long[] res = new long[queries.length];
        for (int i = 0; i < queries.length; i++)
            res[i] = queries[i] <= pals.size() ? pals.get(queries[i] - 1) : -1;
        return res;
    }
};

