class Solution {
    public long[] kthPalindrome(int[] queries, int intLength) {
        int halfLen = (intLength + 1) / 2;
        long start = 1;
        for (int i = 0; i < halfLen - 1; i++) start *= 10;
        long capacity = 9 * start;
        long[] res = new long[queries.length];
        for (int i = 0; i < queries.length; i++) {
            if (queries[i] > capacity) { res[i] = -1; continue; }
            StringBuilder sb = new StringBuilder(String.valueOf(start + queries[i] - 1));
            String rev = new StringBuilder(sb.substring(0, intLength - halfLen)).reverse().toString();
            res[i] = Long.parseLong(sb.append(rev).toString());
        }
        return res;
    }
};

